$('exportDialog').addEventListener('click',event=>{if(event.target!==$('exportDialog'))return;const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeExportDialog();});
$('exportDialog').addEventListener('keydown',event=>{if(event.key==='Escape'&&typeof event.currentTarget.showModal!=='function'){event.preventDefault();closeExportDialog();}if(event.key==='Tab'){const controls=Array.from(event.currentTarget.querySelectorAll('button,input,textarea,select,a[href]')).filter(el=>!el.disabled&&el.getClientRects().length),first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
function generate(){openExportDialog();checkpoint();try{$('htmlOutput').value=clean();$('ao3Report').hidden=false;$('ao3Report').textContent='当前章 HTML：'+$('htmlOutput').value.length.toLocaleString()+' 字符。'+(ao3FlashMode()==='reveal'?'屏闪已转换为点击揭示，无需 GIF。':'使用单次 GIF；播放时机由浏览器决定。')+'通用 CSS 配置一次，之后复制 HTML。分支收束会增加代码，建议低于 45 万字符。';}catch(error){$('htmlOutput').value='';$('outputPanel').hidden=false;$('ao3Report').hidden=false;$('ao3Report').textContent='当前章未导出：'+error.message+'\n可点击“检查并下载 AO3 分章包”，单独检查其他已保存章节。';notice('无法生成：'+error.message);return false;}$('cssOutput').value=$('noCSS').checked?'':css;$('outputPanel').hidden=false;$('cssTab').hidden=$('noCSS').checked;showCode('html');notice('代码已生成。');return true;}
function updateAO3ExportMode(){const gif=ao3FlashMode()==='gif';$('prepareAO3GIFs').hidden=!gif;$('ao3ModeHelp').textContent=gif?'可一键生成并上传本章的独立及物件附加屏闪 GIF，自动填入直链；需已连接 GitHub。GIF 可能提前播放，双层文字保留点击切换。':'简化模式会把屏闪转换为点击揭示；图片使用已有 HTTPS 直链。通用 CSS 更新一次后，后续只需复制章节 HTML。';}
$('ao3FlashMode').onchange=()=>{updateAO3ExportMode();if(!$('outputPanel').hidden)generate();};
$('prepareAO3GIFs').onclick=async()=>{if(await prepareAO3ChapterGIFs())generate();};
$('copyAO3Chapter').onclick=async()=>{if(!generate())return;try{await navigator.clipboard.writeText($('htmlOutput').value);notice('本章 HTML 已复制，粘贴到 AO3 的 HTML 编辑器即可。');}catch{$('htmlOutput').focus();$('htmlOutput').select();$('ao3Report').textContent+='\n浏览器未允许自动复制，代码已全选，请使用系统复制。';notice('代码已全选，请使用系统复制。');}};
$('generate').onclick=generate;$('noCSS').onchange=()=>{if(!$('outputPanel').hidden)generate();};$('htmlTab').onclick=()=>showCode('html');$('cssTab').onclick=()=>showCode('css');
function download(name,content,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),60000);}
document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const t=$(b.dataset.copy);if(!t.value)return notice('请先生成代码，复制 CSS 前取消勾选「不要 CSS」。');try{await navigator.clipboard.writeText(t.value);notice('已复制。');}catch{t.focus();t.select();notice('请使用系统复制操作复制选中的代码。');}});
function saveLocalDocument(){showFilePanel(true);persist();const stamp=new Date().toISOString().replace(/[:.]/g,'-');download('纸间-正文-'+stamp+'.json',JSON.stringify(documentRecord(),null,2),'application/json');notice('已请求下载；若没有弹出保存，请在草稿面板复制完整内容。');}
function showFilePanel(saving){$('filePanel').hidden=false;$('filePanelTitle').textContent=saving?'保存草稿':'打开草稿';$('portableText').value=saving?JSON.stringify(documentRecord(),null,2):'';$('filePanelStatus').textContent='';$('filePanel').scrollIntoView({block:'center',behavior:'smooth'});}
$('closeFilePanel').onclick=()=>$('filePanel').hidden=true;
$('portableFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{$('portableText').value=await file.text();$('filePanelStatus').textContent='文件已读取，点击「导入草稿」。';}catch{$('filePanelStatus').textContent='无法读取文件，请粘贴 JSON 文件内容。';}};
$('importPortable').onclick=()=>{try{loadDocument(parseDocument($('portableText').value));$('filePanel').hidden=true;}catch{$('filePanelStatus').textContent='无法导入：请使用完整的纸间 JSON 草稿文件内容。';}};
$('copyPortable').onclick=async()=>{const area=$('portableText');try{await navigator.clipboard.writeText(area.value);$('filePanelStatus').textContent='草稿已复制，请粘贴到本地文本文件中保存。';}catch{area.focus();area.select();area.setSelectionRange(0,area.value.length);$('filePanelStatus').textContent='请长按选中文字，使用系统复制，再保存到本地文本文件。';}};
$('downloadPortable').onclick=()=>download('纸间-草稿.json',$('portableText').value,'application/json');
$('saveDocument').onclick=saveLocalDocument;
$('openDocument').onclick=()=>showFilePanel(false);
$('documentFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const record=parseDocument(await file.text());loadDocument(record);}catch{notice('无法打开：请选择纸间「保存到本地」生成的 JSON 正文文件。');}};
$('restoreBackup').onclick=()=>{const record=readStored(BACKUP_KEY)||readStored('paper-studio-backup-v3');if(!record)return notice('当前浏览器没有可恢复的备份。');loadDocument(record);};
for(const id of ['storyFull','noCSS','storyTheme'])$(id).addEventListener('change',()=>{checkpoint();persist();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&!e.altKey&&e.key.toLowerCase()==='s'){e.preventDefault();saveLocalDocument();}});
window.addEventListener('pagehide',persist);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persist();});
$('downloadHTML').onclick=exportMinitoolZIP;$('exportBookZIP').onclick=exportMinitoolZIP;

function editBody(h,field='body'){return `<div class="edit-body" data-field="${field}" data-placeholder="${field==='option-body'?'填写这条分支的剧情…':'输入正文…'}" data-editable="true" contenteditable="true">${h}</div>`;}
function editField(value,field,label){return `<label class="inline-field"><span class="field-label">${label}</span><span class="edit-field" data-field="${field}" data-placeholder="可留空" data-editable="true" contenteditable="true">${esc(value)}</span></label>`;}
function afterTextField(){return '<div class="after-text-field" data-field="after-text" data-editable="true" contenteditable="true" data-placeholder="在此效果下方继续写正文…"></div>';}
function editBlock(type,label,body){return `<div class="widget edit-block" data-widget="${type}" contenteditable="false"><div class="block-caption"><span>${label}</span><button data-action="remove-block" title="移除效果，保留文字" aria-label="移除${label}效果">×</button></div>${body}${type==='branch'?'':afterTextField()}</div>`;}
function letter(text,sender='',recipient=''){return editBlock('letter','书信',`<div class="letter-fields">${editField(sender,'sender','来信人')}${editField(recipient,'recipient','收信人')}</div>${editBody(paragraphs(text))}`);}

let imageAssets={},imageTarget='preview';

function flash(text=''){return editBlock('flash','屏幕突闪',`<div class="picture-fields">${editField('','flash-text','频闪文字')}${editField('plain','flash-text-mode','频闪文字样式：plain / chaos')}${editField('white','flash-text-color','频闪文字颜色：white / black / red')}${editField('100','flash-duration','屏闪持续时间（毫秒）')}${editField('red','flash-color','颜色：red / blue / green')}${editField('0','flash-delay','小工具进入本页后延迟毫秒（0 / 500 / 1000 / 2000）')}<div class="image-local-field">${editField('','image-asset','叠加图片引用')}</div><button data-action="choose-image" type="button">选择叠加图片（可选）</button>${editField('','image-url','叠加图片 HTTPS（可选）')}${editField('','image-alt','图片描述')}${editField('','flash-gif-url','AO3 单次 GIF 直链')}<button data-action="download-flash-gif" type="button">下载 AO3 单次 GIF</button><p class="flash-editor-note">小工具进入本页自动突闪，时长可设置，同次阅读仅一次。AO3 默认简化导出，无需 GIF；选择保留 GIF 时可在导出窗口一键生成上传，播放时机不保证。</p></div>${editBody(paragraphs(text))}`);}
function flashColor(source){const value=fieldText(source,'flash-color');return ['red','blue','green','white','black'].includes(value)?value:'red';}
function flashDuration(source){const value=Number(fieldText(source,'flash-duration'));return [100,200,300,500,1000].includes(value)?value:100;}
function flashDelay(source){const value=Number(fieldText(source,'flash-delay'));return [0,500,1000,2000].includes(value)?value:0;}
function ao3FlashMode(){return $('ao3FlashMode')?.value==='gif'?'gif':'reveal';}
function ao3RevealCopy(text,mode,color,packed=true){return '<div class="ao3-flash-copy ao3-ink-'+(['white','black','red'].includes(color)?color:'white')+'">'+(mode==='chaos'?fontMarkup('chaos',text,false,{packed}):esc(text).replace(/\n/g,'<br>'))+'</div>';}
function renderAO3FlashReveal(source,normal,standalone=true){const color=flashColor(source),remote=imageLink(fieldText(source,'image-url'));if(localImageURL(source)&&!remote)throw Error('AO3 隐藏图片尚未填写 HTTPS 直链，请在素材库上传并自动填写；不需要制作 GIF。');const text=fieldText(source,'flash-text'),copy=text.trim()?ao3RevealCopy(text,fieldText(source,'flash-text-mode'),fieldText(source,'flash-text-color'),fieldText(source,'flash-density')!=='normal'):'';return '<div class="'+(standalone?'flash-scene flash-ao3-static':'attached-flash-scene')+'">'+normal+'<details class="ao3-flash-reveal"><summary class="option-btn">点击查看隐藏内容</summary><div class="ao3-flash-panel ao3-flash-'+color+'">'+(remote?'<img class="ao3-flash-image'+imagePositionClasses(source)+'" width="'+flashImageWidth(source)+'%" src="'+esc(remote)+'" alt="'+esc(fieldText(source,'image-alt'))+'">':'')+copy+(!remote&&!copy?'<span class="ao3-flash-color-pad" aria-label="隐藏画面"></span>':'')+'</div></details></div>';}
function simplifyAO3DoubleFlashes(root){for(const detail of root.querySelectorAll('details.double-text')){const back=detail.querySelector('.double-back');if(!back)continue;const overlays=[...back.querySelectorAll('.flash-overlay-copy')];for(const overlay of overlays){const text=overlay.textContent;overlay.remove();if(text.trim()&&!back.textContent.includes(text)){const color=overlay.classList.contains('flash-ink-red')?'red':overlay.classList.contains('flash-ink-black')?'black':'white';const background=['red','blue','green','white','black'].find(c=>detail.classList.contains('flash-'+c)||back.classList.contains('flash-'+c))||'black';back.insertAdjacentHTML('beforeend','<span class="ao3-flash-panel ao3-flash-'+background+'">'+ao3RevealCopy(text,overlay.classList.contains('flash-copy-chaos')?'chaos':'plain',color,!overlay.classList.contains('flash-density-normal'))+'</span>');}}for(const el of [detail,back])for(const name of [...el.classList])if(name.startsWith('flash-'))el.classList.remove(name);}}
function renderFlash(source){const base=renderFlashBase(source);const color=flashColor(source),url=localImageURL(source)||imageLink(fieldText(source,'image-url')),alt=fieldText(source,'image-alt'),body=partsHTML(renderParts(source.querySelector('[data-field=body]')));if(imageTarget==='ao3'){if(ao3FlashMode()==='reveal')return renderAO3FlashReveal(source,'<div class="flash-body">'+base+body+'</div>');const gif=imageLink(fieldText(source,'flash-gif-url'));if(!gif)throw Error('屏幕突闪：请选择简化导出，或点击「生成并上传本章屏闪 GIF」。小红书 ZIP 无需 GIF。');return '<div class="flash-scene flash-ao3"><img class="flash-ao3-gif" src="'+esc(gif)+'" alt="短暂'+({red:'红',blue:'蓝',green:'绿',white:'白',black:'黑'}[color])+'色突闪"><div class="flash-body">'+base+body+'</div></div>';}
return '<div class="flash-scene flash-enabled flash-'+color+' flash-wait-'+flashDelay(source)+' flash-duration-'+flashDuration(source)+'">'+(url?'<img class="flash-optional-image'+imagePositionClasses(source)+'" width="'+flashImageWidth(source)+'%" src="'+esc(url)+'" alt="'+esc(alt)+'">':'')+flashCopyMarkup(source)+'<div class="flash-body">'+base+body+'</div></div>';}
function flashCopyMarkup(source){const text=fieldText(source,'flash-text');if(!text.trim())return '';const mode=fieldText(source,'flash-text-mode')==='chaos'?'chaos':'plain',raw=fieldText(source,'flash-text-color'),color=['white','black','red'].includes(raw)?raw:'white';return flashCopyHTML(text,mode,color,fieldText(source,'flash-density')!=='normal');}
function flashCopyHTML(text,mode='plain',color='white',packed=fontOptions().packed){if(!text.trim())return '';return '<div class="flash-overlay-copy flash-copy-'+(mode==='chaos'?'chaos':'plain')+' flash-ink-'+(['white','black','red'].includes(color)?color:'white')+' flash-density-'+(packed?'packed':'normal')+'">'+esc(text)+'</div>';}
function ensureAttachedFlashFields(source){let host=source.querySelector('.picture-fields');if(!host){host=document.createElement('div');host.className='picture-fields attached-flash-fields';source.prepend(host);}for(const [key,value] of [['flash-color','red'],['flash-delay','0'],['flash-duration','100'],['flash-density','packed'],['flash-text',''],['flash-text-mode','plain'],['flash-text-color','white'],['image-asset',''],['image-url',''],['image-alt',''],['flash-gif-url','']])if(!source.querySelector('[data-field="'+key+'"]'))host.insertAdjacentHTML('beforeend',editField(value,key,key));}
function appendFlashFields(fields,source){appendImagePositionReset(fields,source);ensureAttachedFlashFields(source);if(source.dataset.widget==='flash')appendFlashBaseFields(fields,source);appendVisualImageSizing(fields,source,{caption:'突闪图片'});
 for(const [key,value] of [['flash-duration','100'],['flash-density','packed'],['flash-text',''],['flash-text-mode','plain'],['flash-text-color','white']])if(!source.querySelector('[data-field="'+key+'"]'))source.querySelector('.picture-fields').insertAdjacentHTML('beforeend',editField(value,key,key));
 const textLabel=document.createElement('label'),textInput=document.createElement('textarea');textLabel.textContent='频闪文字';textInput.setAttribute('aria-label','频闪文字');textInput.dataset.graphField='flash-text';textInput.value=fieldText(source,'flash-text');textInput.placeholder='仅在闪屏时显示，可留空';textLabel.append(textInput);fields.append(textLabel);
 for(const [key,title,options] of [['flash-density','乱码密度',[['normal','普通'],['packed','密集']]],['flash-text-mode','频闪文字样式',[['plain','普通文字'],['chaos','全屏乱码']]],['flash-text-color','频闪文字颜色',[['white','白色'],['black','黑色'],['red','红色']]]]){const label=document.createElement('label'),select=document.createElement('select');label.textContent=title;select.setAttribute('aria-label',title);select.dataset.graphField=key;for(const [value,name] of options){const option=document.createElement('option');option.value=value;option.textContent=name;select.append(option);}select.value=fieldText(source,key);label.append(select);fields.append(label);}
 const explanation=document.createElement('p');explanation.className='flash-editor-note';explanation.textContent='频闪文字只在设定时长的闪屏中显示；节点正文是闪屏结束后仍留在剧情页上的文字。全屏乱码会铺满屏幕，颜色与文字均可设置。';fields.append(explanation);
for(const [field,labelText,values] of [['flash-duration','屏闪持续时间',[['100','0.1 秒'],['200','0.2 秒'],['300','0.3 秒'],['500','0.5 秒'],['1000','1 秒']]],['flash-color','突闪颜色',[['red','红色'],['blue','蓝色'],['green','绿色'],['white','白色'],['black','黑色']]],['flash-delay','小工具进入本页后延迟',[['0','立即'],['500','0.5 秒'],['1000','1 秒'],['2000','2 秒']]]]){const label=document.createElement('label'),select=document.createElement('select');label.textContent=labelText;select.setAttribute('aria-label',labelText);select.dataset.graphField=field;for(const [value,text] of values){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=fieldText(source,field)||values[0][0];label.append(select);fields.append(label);}for(const [field,labelText] of [['image-url','叠加图片 HTTPS（可选）'],['image-alt','图片描述'],['flash-gif-url','AO3 单次 GIF 直链']]){const label=document.createElement('label'),input=document.createElement('input');label.textContent=labelText;input.dataset.graphField=field;input.value=fieldText(source,field);label.append(input);fields.append(label);}const input=document.createElement('input');input.type='file';input.accept='.png,.jpg,.jpeg,.gif,.webp';input.setAttribute('aria-label','突闪叠加图片');input.onchange=()=>{if(input.files[0])attachPictureFile(source,input.files[0]).catch(error=>notice(error.message));};const remove=document.createElement('button');remove.textContent='移除叠加图片';remove.onclick=()=>{checkpoint();source.querySelector('[data-field=image-asset]').textContent='';source.querySelector('[data-field=image-url]').textContent='';checkpoint();renderGraph(source);};const button=document.createElement('button');button.textContent='下载 AO3 单次 GIF';button.onclick=()=>downloadFlashGIF(source);const note=document.createElement('p');note.className='flash-editor-note';const asset=imageAssets[fieldText(source,'image-asset')];note.textContent=(asset?'叠加图片：'+asset.name+'。':'不选图片时仅闪颜色。')+'持续时间按设置播放，同次阅读仅一次；读者可关闭。AO3 为近似 GIF，可能提前播放。颜色、图片或频闪文字变化后请重新生成 GIF。';fields.append(input,remove,button,note);appendGitHubUpload(fields,source,'flash');}
function encodeSingleFlashGIF(width,height,pixels,duration=100){const bytes=[],push=(...n)=>bytes.push(...n),word=n=>push(n&255,n>>8&255);for(const c of 'GIF89a')push(c.charCodeAt(0));word(width);word(height);push(247,0,0);for(let i=0;i<256;i++){const index=i===1?0:i;push(Math.round((index>>5&7)*255/7),Math.round((index>>2&7)*255/7),Math.round((index&3)*255/3));}
function frame(w,h,indices,delay){push(33,249,4,9);word(delay);push(0,0,44);word(0);word(0);word(w);word(h);push(0,8);const codes=[];for(let i=0;i<indices.length;i+=128){codes.push(256);for(let j=i;j<Math.min(indices.length,i+128);j++)codes.push(indices[j]);}codes.push(257);const packed=[];let bits=0,buffer=0;for(const code of codes){buffer|=code<<bits;bits+=9;while(bits>=8){packed.push(buffer&255);buffer>>>=8;bits-=8;}}if(bits)packed.push(buffer&255);for(let i=0;i<packed.length;i+=255){const chunk=packed.slice(i,i+255);push(chunk.length,...chunk);}push(0);}
frame(width,height,pixels,Math.round(duration/10));frame(1,1,[0],1);push(59);return new Blob([new Uint8Array(bytes)],{type:'image/gif'});}
async function makeFlashGIF(source){const url=localImageURL(source)||imageLink(fieldText(source,'image-url')),color=flashColor(source),canvas=document.createElement('canvas');canvas.width=url||fieldText(source,'flash-text').trim()?480:1;canvas.height=url||fieldText(source,'flash-text').trim()?720:1;const context=canvas.getContext('2d');context.fillStyle={red:'#ff0000',blue:'#0000ff',green:'#00ff00',white:'#ffffff',black:'#000000'}[color];context.fillRect(0,0,canvas.width,canvas.height);if(url){const image=await new Promise((resolve,reject)=>{const image=new Image();if(!url.startsWith('data:'))image.crossOrigin='anonymous';const timer=setTimeout(()=>reject(Error('图片读取超时，请使用本地叠加图片')),15000);image.onload=()=>{clearTimeout(timer);resolve(image);};image.onerror=()=>{clearTimeout(timer);reject(Error('图片无法转换 GIF，请选择本地图片后重试'));};image.src=url;});const scale=Math.min(canvas.width/image.naturalWidth,canvas.height/image.naturalHeight)*flashImageWidth(source)/100,w=image.naturalWidth*scale,h=image.naturalHeight*scale;context.drawImage(image,(canvas.width-w)/2+canvas.width*imagePositionValue(source,'image-x')/100,(canvas.height-h)/2+h*imagePositionValue(source,'image-y')/100,w,h);}paintFlashCopy(context,canvas.width,canvas.height,source);const rgba=context.getImageData(0,0,canvas.width,canvas.height).data,pixels=new Uint8Array(canvas.width*canvas.height);for(let i=0;i<pixels.length;i++){const index=(rgba[i*4]>>5)<<5|(rgba[i*4+1]>>5)<<2|rgba[i*4+2]>>6;pixels[i]=index===0?1:index;}return encodeSingleFlashGIF(canvas.width,canvas.height,pixels,flashDuration(source));}
async function downloadFlashGIF(source){try{const blob=await makeFlashGIF(source);download('纸间-'+flashColor(source)+'-单次突闪.gif',blob,'image/gif');notice('已生成单次 GIF：颜色、图片与文字按设定时长显示后透明，不循环。上传图床后填写 AO3 GIF 直链；AO3 可能提前播放。');}catch(error){notice(error.message);}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action=download-flash-gif]');if(button){event.preventDefault();downloadFlashGIF(button.closest('[data-widget=flash]'));}});
const screenFlashCSS='.screen-flash-overlay{position:fixed;left:0;top:0;width:100%;height:100%;z-index:2147483000;display:flex;align-items:center;justify-content:center;pointer-events:none}.screen-flash-overlay[hidden]{display:none}.screen-flash-overlay img{display:block;width:auto;height:auto;max-width:100%;max-height:100%}.screen-flash-overlay .flash-overlay-copy{position:absolute;left:0;top:0;width:100%;height:100%;overflow:hidden;display:flex;align-items:center;justify-content:center;text-align:center;font:clamp(24px,6vw,64px)/1.25 serif;white-space:pre-wrap;padding:5%;box-sizing:border-box}.screen-flash-overlay .flash-copy-chaos{display:block;padding:0}.screen-flash-control{font:12px/1.5 sans-serif;flex-basis:100%;padding:6px;background:#f7efe4;color:#633d2a}.screen-flash-control button{font:inherit;margin-left:8px;padding:5px;border:1px solid #aaa;border-radius:4px;background:#fff;color:#333}';
