function cameraCanvas(text=''){return editBlock('camera','逃跑画布','<div class="picture-fields"><div class="image-local-field">'+editField('','image-asset','本地图片引用')+'</div><button type="button" data-action="choose-image">选择场景大图</button>'+editField('','image-url','图片 HTTPS 直链')+editField('','image-alt','场景描述')+editField('15','camera-start-x','镜头起点 X')+editField('50','camera-start-y','镜头起点 Y')+editField('85','camera-end-x','镜头终点 X')+editField('50','camera-end-y','镜头终点 Y')+editField('1.8','camera-zoom','镜头放大')+editField('6','camera-duration','移动秒数')+'</div>'+editBody(paragraphs(text)));}
function cameraSettings(source){const number=(name,fallback,min,max)=>{const raw=fieldText(source,name);const n=raw===''?fallback:Number(raw);return Math.max(min,Math.min(max,isFinite(n)?n:fallback));};return {sx:number('camera-start-x',15,0,100),sy:number('camera-start-y',50,0,100),ex:number('camera-end-x',85,0,100),ey:number('camera-end-y',50,0,100),zoom:number('camera-zoom',1.8,1,4),duration:number('camera-duration',6,.5,60)};}
