const interactiveSceneCSS='.interactive-scene{width:100%;text-align:center}.interactive-board{pointer-events:auto;position:relative;display:inline-block;max-width:100%;vertical-align:top;line-height:0}.interactive-background{display:block;max-width:100%;max-height:50vh;width:auto;height:auto;margin:0 auto}.interactive-hotspot{position:absolute;display:block;padding:0;margin:0;border:0;background:transparent;color:#fff;cursor:pointer;font:13px/1.4 sans-serif;min-height:0}.interactive-hotspot>span{display:inline-block;padding:3px 6px;background:rgba(0,0,0,.6);border-radius:4px}.interactive-hotspot.labels-hidden>span{opacity:0}.interactive-hotspot:focus{outline:2px solid #e5be54;outline-offset:2px}.interactive-hotspot:focus>span,.interactive-hotspot:hover>span{opacity:1}.interactive-caption{padding:14px 20px;line-height:1.8}.interactive-empty{width:320px;max-width:100%;height:180px;background:#ddd;color:#333;line-height:1.8;padding:20px;box-sizing:border-box}.interactive-investigation[hidden]{display:none!important}.interactive-investigation{position:fixed;top:0;right:0;bottom:0;left:0;z-index:14000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.55);padding:16px;box-sizing:border-box}.interactive-investigation>section{width:100%;max-width:500px;max-height:80vh;overflow:auto;padding:22px;border:1px solid var(--reader-border,#aaa);border-radius:var(--skin-radius,10px);background:var(--skin-panel,var(--reader-bg,#fff));color:var(--skin-text,var(--reader-fg,#333));font:16px/1.8 sans-serif;text-align:left}.interactive-investigation p{white-space:pre-wrap;color:inherit}.interactive-investigation button{padding:8px 16px;border:1px solid currentColor;background:transparent;color:inherit;border-radius:5px}';
