 overlay.className='interactive-investigation';overlay.hidden=true;overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','文字说明');close.type='button';close.textContent='继续';panel.appendChild(heading);panel.appendChild(text);panel.appendChild(close);overlay.appendChild(panel);document.body.appendChild(overlay);
