function mapTemplate(size=3){const cells=[];for(let y=0;y<size;y++)for(let x=0;x<size;x++){const id='place-'+y+'-'+x;cells.push({id,name:'地点 '+(y*size+x+1),x,y,imageAsset:'',imageUrl:'',text:'',links:{up:y?'place-'+(y-1)+'-'+x:'',down:y<size-1?'place-'+(y+1)+'-'+x:'',left:x?'place-'+y+'-'+(x-1):'',right:x<size-1?'place-'+y+'-'+(x+1):''},target:'',hp:0,san:0,once:true,requireItem:'',setFlag:''});}return {start:cells[0].id,limit:12,failureTarget:'',showSteps:false,cells};}
