 'use strict';var doc=target||document,body=doc.body;if(!body)return;var host=doc.querySelector('[data-work-skin]');if(!config&&host){try{config=JSON.parse(host.getAttribute('data-work-skin'));}catch(ignored){}}
 body.classList.remove('paper-work-skin','paper-skin-monochrome','paper-skin-archive','paper-skin-theatre','paper-skin-custom','paper-skin-filled','paper-skin-sms');['accent','panel','text','border','radius','on-accent'].forEach(function(key){body.style.removeProperty('--skin-'+key);});
 if(!config||!['monochrome','archive','theatre','custom'].includes(config.preset))return;var colors={accent:'#715d3f',panel:'#eee5d0',text:'#40382e',border:'#a79779'};Object.keys(colors).forEach(function(key){var value=/^#[a-f0-9]{6}$/i.test(config[key]||'')?config[key]:colors[key];body.style.setProperty('--skin-'+key,value);});var accent=body.style.getPropertyValue('--skin-accent').slice(1),light=(parseInt(accent.slice(0,2),16)*299+parseInt(accent.slice(2,4),16)*587+parseInt(accent.slice(4,6),16)*114)/1000;body.style.setProperty('--skin-on-accent',light>155?'#171717':'#ffffff');body.style.setProperty('--skin-radius',Math.max(0,Math.min(24,Number(config.radius)||0))+'px');body.classList.add('paper-work-skin','paper-skin-'+config.preset);if(config.buttons==='filled')body.classList.add('paper-skin-filled');if(config.sms===true)body.classList.add('paper-skin-sms');
