function normalizeReaderStats(value){const clean=value&&typeof value==='object'?value:{},result={enabled:clean.enabled===true};for(const name of ['hp','san']){const old=clean[name]&&typeof clean[name]==='object'?clean[name]:{},max=Math.max(1,Math.min(1000000,Math.round(Number(old.max)||100))),initial=old.initial===undefined?max:Math.max(0,Math.min(max,Math.round(Number(old.initial)||0)));result[name]={max,initial,show:old.show!==false};}return result;}
function readerStatNode(source){const result={};for(const name of ['hp','san'])for(const suffix of ['Delta','Min','Max']){const key=name+suffix,value=source.dataset['stat'+name[0].toUpperCase()+name.slice(1)+suffix];if(value!==undefined&&value!==''&&isFinite(Number(value)))result[key]=Math.max(-1000000,Math.min(1000000,Math.round(Number(value))));}return result;}
