 if(scope==='page'&&kind==='branch')return;
 const section=document.createElement('details'),summary=document.createElement('summary');section.className='reader-stat-settings';summary.textContent='血量与 SAN';section.append(summary);panel.append(section);const config=normalizeReaderStats(book.readerStats);
