 Promise.all([compatibleRecord(),endingCollection.ready]).then(([value])=>{if(value&&value.version===1&&value.states&&typeof value.states==='object'&&chapters.some(c=>c.getAttribute('data-chapter-id')===value.current)){pending=value;resume.querySelector('span').textContent=oldNodeState(value)?'检测到旧版进度：保留章节和标记，阅读位置从该章开头恢复':'有上次的阅读进度';resume.hidden=false;fit();}loading=false;if(isPreview&&root.getAttribute('data-preview-entry')==='story'){pending=null;const chapterId=root.getAttribute('data-preview-chapter'),index=chapters.findIndex(c=>c.getAttribute('data-chapter-id')===chapterId);dismissCover();show(index<0?0:index);root.dispatchEvent(new Event('paper-reader-ready'));library.remember();window.dispatchEvent(new Event('resize'));}else paintCover();}).catch(failStorage);
