 if($('toolCategory').value==='sound'){if(item?.source?.isConnected&&item.kind!=='choice'&&inspectorDismissed!==item.source){openNodeSounds(item.source);}else{panel.hidden=true;document.querySelector('.workspace').classList.remove('inspector-open');}syncSidebarChrome(item);return;}
