 panel.hidden=!visible;document.querySelector('.workspace').classList.toggle('inspector-open',!!visible);
 if(!visible){inspectorSource=null;syncSidebarChrome(item);return;}inspectorSource=item.source;$('effectInspectorTitle').textContent=item.label+'设置';if($('effectInspectorBody').firstElementChild!==item.settings)$('effectInspectorBody').replaceChildren(item.settings);syncSidebarChrome(item);
