function installPageMedia(){
 var nodes=Array.from(document.querySelectorAll('#workskin .media-auto-enabled'));if(!nodes.length)return;var enabled=true,armed=false,played=new WeakSet(),pending=new WeakSet(),queued=false,button=document.createElement('button');button.className='page-media-toggle';button.type='button';var nav=document.querySelector('.reader-nav');if(nav)nav.appendChild(button);else document.body.insertBefore(button,document.body.firstChild);
 function sync(){button.textContent=enabled?'自动播放：开启':'自动播放：关闭';button.setAttribute('aria-pressed',String(enabled));window.dispatchEvent(new Event('resize'));}
 function visible(el){if(el.classList.contains('media-preparing')||document.hidden||el.closest('[hidden]'))return false;for(var p=el.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS'&&!p.open){var summary=Array.from(p.children).find(function(c){return c.tagName==='SUMMARY';});if(!summary||!summary.contains(el))return false;}var r=el.getBoundingClientRect();if(!r.width||!r.height||r.bottom<=0||r.top>=innerHeight)return false;var hit=document.elementFromPoint(Math.max(0,Math.min(innerWidth-1,r.left+r.width/2)),Math.max(0,Math.min(innerHeight-1,Math.max(0,r.top)+Math.min(40,r.height/2))));return !!(hit&&(el.contains(hit)||(hit.closest('.effect-advance')&&hit.closest('.effect-page')===el.closest('.effect-page'))));}
 function check(){queued=false;nodes.forEach(function(el){var shown=visible(el);if(el.tagName==='VIDEO'&&!shown){if(played.has(el))el.pause();played.delete(el);}if(!enabled||!armed||!shown||played.has(el)||pending.has(el))return;pending.add(el);var result;if(el.tagName==='VIDEO')result=el.play();else{var detail={card:el,result:null};el.dispatchEvent(new CustomEvent('paper-page-autoplay',{bubbles:true,detail:detail}));result=detail.result;}Promise.resolve(result).then(function(){pending.delete(el);played.add(el);},function(){pending.delete(el);button.textContent='点击开启自动播放';});});}
 function schedule(){if(!queued){queued=true;requestAnimationFrame(check);}}button.onclick=function(){enabled=button.textContent==='点击开启自动播放'?true:!enabled;armed=true;if(!enabled)nodes.forEach(function(el){if(el.tagName==='VIDEO'&&played.has(el)){el.pause();played.delete(el);}});sync();schedule();};document.addEventListener('click',function(){armed=true;schedule();},true);document.addEventListener('toggle',schedule,true);document.addEventListener('scroll',schedule,true);document.addEventListener('paper-media-ready',schedule);window.addEventListener('resize',schedule);document.addEventListener('visibilitychange',schedule);sync();schedule();
}
