function installEmbeddedVideos(){var urls=[],pending={};function prepare(key,data){if(pending[key])return pending[key];var sdk=window.xhs&&window.xhs.miniTool;pending[key]=new Promise(function(resolve){function fallback(){var binary=atob(data),bytes=new Uint8Array(binary.length);for(var i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);var url=URL.createObjectURL(new Blob([bytes],{type:'video/mp4'}));urls.push(url);resolve(url);}if(!sdk||typeof sdk.writeTempFile!=='function')return fallback();var done=false,timer=setTimeout(fail,10000);function fail(){if(done)return;done=true;clearTimeout(timer);fallback();}function success(result){if(done)return;if(!result||typeof result.filePath!=='string')return fail();done=true;clearTimeout(timer);resolve(result.filePath);}try{var result=sdk.writeTempFile({data:'data:video/mp4;base64,'+data,success:success,fail:fail});if(result&&typeof result.then==='function')result.then(success,fail);}catch(error){fail();}});return pending[key];}document.querySelectorAll('video[data-local-video]').forEach(function(video){var key=Number(video.getAttribute('data-local-video')),data=(window.PAPER_VIDEOS||[])[key];if(!data)return;video.classList.add('media-preparing');prepare(key,data).then(function(url){video.src=url;video.classList.remove('media-preparing');document.dispatchEvent(new Event('paper-media-ready'));});video.addEventListener('error',function(){var note=video.nextElementSibling;if(!note||!note.classList.contains('video-playback-error')){note=document.createElement('p');note.className='video-playback-error';video.parentNode.insertBefore(note,video.nextSibling);}note.textContent='当前环境无法播放此视频，请检查平台视频支持或编码格式。';});});window.addEventListener('pagehide',function(){urls.forEach(function(url){URL.revokeObjectURL(url);});});}

