 function row(title,el,kind){const line=document.createElement('div');line.className='applied-effect-row';const label=document.createElement('span');label.textContent=title;line.append(label);for(const [caption,action] of [['调整',()=>editAppliedEffect(el,kind)],['移除',()=>removeAppliedEffect(el,kind)]]){const button=document.createElement('button');button.type='button';button.textContent=caption;button.onmousedown=e=>e.preventDefault();button.onclick=action;line.append(button);}list.append(line);}
