 if(source?.dataset.textAlign||source?.dataset.pagePosition)row('本页排版',source,'layout');if(source?.dataset.timelineSounds)row('声音时间轴 · '+timelineSounds(source).length+' 段',source,'timeline');if(source?.dataset.pageFlash==='yes')row('本页屏闪',source,'pageFlash');if(source?.dataset.soundUrl||source?.dataset.soundMode==='stop')row(source.dataset.soundMode==='stop'?'停止持续音效':source.dataset.soundMode==='start'?'开始持续音效':'本页音效',source,'sound');
 let effects=[...(host.matches(APPLIED_SELECTOR)?[host]:[]),...host.querySelectorAll(APPLIED_SELECTOR)];
 const nearest=target?.closest(APPLIED_SELECTOR);if(nearest&&host.contains(nearest)){const relevant=effects.filter(el=>el===nearest||el.contains(nearest)||nearest.contains(el));if(relevant.length)effects=relevant;}
 if(target&&!nearest){const selection=getSelection(),range=selection.rangeCount&&!selection.isCollapsed?selection.getRangeAt(0):null;effects=range&&host.contains(range.commonAncestorContainer)?effects.filter(el=>range.intersectsNode(el)):[];}effects=effects.filter(el=>!el.closest('.flash-overlay-copy')&&(!el.matches('.text-style')||el.matches('.text-appear-type,.text-appear-fade,.text-appear-scroll,.text-large,.text-huge,.text-bold')));
 effects.forEach(el=>{let title;if(el.matches('.details-inline-blur'))title='字体模糊 · '+({1:'轻度',2:'中度',3:'重度'}[blurLevelOf(el)]);else if(el.matches('.font-art'))title='乱码 · '+(fontOptions(el).packed?'密集':'普通');else if(el.matches('.inline-spoiler,.inline-red-text'))title=el.matches('.inline-spoiler')?'红色字体 · 点击展开':'红字 · 直接显示';else if(el.matches('.double-text'))title='双层文字'+(el.classList.contains('flash-enabled')?' · 屏闪':'');else title=[el.classList.contains('text-appear-scroll')?'向上滚动':el.classList.contains('text-appear-type')?'打字出现':el.classList.contains('text-appear-fade')?'缓慢浮现':'文字样式',el.classList.contains('text-huge')?'更大':el.classList.contains('text-large')?'放大':'',el.classList.contains('text-bold')?'加粗':''].filter(Boolean).join(' · ');const text=(el.querySelector('.font-original,.double-front')||el).textContent.trim();row(title+(text?'：'+text.slice(0,14):''),el,'text');});
