 root.addEventListener('click',function(event){var ending=event.target.closest('.story-ending,.story-ending-page');if(ending){if(event.target.closest('summary,a,input,select,textarea,audio,video,details.double-text,details.inline-spoiler,details.details-inline-blur,details.stack-spoiler')||event.target.closest('button:not(.story-ending-return)'))return;event.preventDefault();event.stopPropagation();if(root.classList.contains('book-reader'))root.dispatchEvent(new Event('paper-story-restart'));else{flags=Object.create(null);root.querySelectorAll('details').forEach(function(d){d.open=false;});root.querySelectorAll('.step-text,.fork-container,.journal-page').forEach(function(el){el.scrollTop=0;});window.scrollTo(0,0);schedule();}return;}var summary=event.target.closest('summary');if(!summary)return;var choice=summary.parentElement;if(!choice.matches('details.story-step')||!choice.parentElement.classList.contains('fork-content'))return;if(choice.hidden){event.preventDefault();return;}if(!choice.open)activate(choice);schedule();});
