 function positionHandle(){if(!selectedImage?.isConnected)return;const rect=selectedImage.getBoundingClientRect();if(moveHandle){moveHandle.style.left=Math.max(0,Math.min(window_.innerWidth-44,rect.left-10))+'px';moveHandle.style.top=Math.max(0,Math.min(window_.innerHeight-26,rect.top-12))+'px';}if(!handle)return;handle.style.left=Math.max(0,Math.min(window_.innerWidth-26,rect.right-13))+'px';handle.style.top=Math.max(0,Math.min(window_.innerHeight-26,rect.bottom-13))+'px';}
 function selectImage(image){$('toolCategory').value='background';syncEffectInspector(item);selectedImage=image;const field=sizeField(image);if(positionPrefix(image))ensureMoveHandle();if(!field){positionHandle();return;}if(!handle){handle=doc.createElement('button');handle.type='button';handle.className='visual-image-handle';handle.textContent='↘';handle.setAttribute('aria-label','拖动调整画面图片大小');doc.querySelector('#workskin').append(handle);handle.addEventListener('pointerdown',event=>{event.preventDefault();event.stopPropagation();if(moveDrag)return;checkpoint();visualDrag=true;const field=sizeField(selectedImage);if(!source.querySelector('[data-field="'+field+'"]'))source.querySelector('.picture-fields').insertAdjacentHTML('beforeend',editField('100',field,'图片大小'));drag={x:event.clientX,value:flashImageWidth(source,field),field,width:Math.max(1,selectedImage.parentElement.getBoundingClientRect().width)};handle.setPointerCapture(event.pointerId);});handle.addEventListener('pointermove',event=>{if(!drag)return;const size=Math.max(10,Math.min(100,Math.round(drag.value+(event.clientX-drag.x)/drag.width*100)));source.querySelector('[data-field="'+drag.field+'"]').textContent=String(size);selectedImage.setAttribute('width',size+'%');positionHandle();});const finish=()=>{if(!drag)return;drag=null;visualDrag=false;checkpoint();persist();renderGraph(source);};handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',finish);handle.addEventListener('lostpointercapture',finish);}positionHandle();}
 function positionPrefix(image){if(image.matches('.flash-base-image'))return 'flash-base';if(image.matches('.story-picture,.flash-optional-image,.polaroid-image-frame img'))return 'image';return '';}
 function ensureMoveHandle(){if(moveHandle)return;moveHandle=doc.createElement('button');moveHandle.type='button';moveHandle.className='visual-image-move';moveHandle.textContent='移动';moveHandle.setAttribute('aria-label','拖动移动图片位置');doc.querySelector('#workskin').append(moveHandle);moveHandle.addEventListener('pointerdown',event=>beginMove(event,selectedImage,moveHandle));}
 function beginMove(event,image,capture){const prefix=image&&positionPrefix(image);if(!current()||!prefix||event.button!==0||drag)return;event.preventDefault();event.stopPropagation();checkpoint();selectImage(image);visualDrag=true;const rect=image.getBoundingClientRect(),parent=image.parentElement.getBoundingClientRect();moveDrag={image,prefix,capture,pointer:event.pointerId,startX:event.clientX,startY:event.clientY,x:imagePositionValue(source,prefix+'-x'),y:imagePositionValue(source,prefix+'-y'),width:Math.max(1,parent.width),height:Math.max(1,rect.height),moved:false};capture.setPointerCapture(event.pointerId);}
