 function finishMove(event,cancel=false){if(!moveDrag||event.pointerId!==moveDrag.pointer)return;const d=moveDrag;moveDrag=null;if(d.capture.hasPointerCapture(d.pointer))d.capture.releasePointerCapture(d.pointer);visualDrag=false;if(!d.moved)return;if(cancel){source.querySelector('[data-field="'+d.prefix+'-x"]').textContent=String(d.x);source.querySelector('[data-field="'+d.prefix+'-y"]').textContent=String(d.y);}checkpoint();persist();renderGraph(source);}
 doc.addEventListener('pointerup',event=>finishMove(event));doc.addEventListener('pointercancel',event=>finishMove(event,true));doc.addEventListener('lostpointercapture',event=>finishMove(event));
