function timelineLiveSource(source){if(source?.isConnected&&editor.contains(source))return source;const id=source?.dataset.nodeId,live=Array.from(editor.querySelectorAll('[data-node-id]')).find(el=>el.dataset.nodeId===id);if(!live)throw Error('声音所在节点已删除，请重新选择声音。');return live;}
