 if(scope==='route'&&choices.length){if(!stored&&isNew&&!base.player&&!source.dataset.soundUrl){const destination=start===source.dataset.nodeId?source:graphMaterialize(nodes.find(n=>n.id===start));writeTimelineSounds(destination,[...timelineSounds(destination).filter(t=>t.id!==base.id),{...clean,routeChoices:choices}]);return;}if(base.routeChoices?.length&&JSON.stringify(base.routeChoices)===JSON.stringify(choices)&&!base.routeOverrides?.length){writeTimelineSounds(source,timelineSounds(source).filter(t=>t.id!==base.id));const destination=start===source.dataset.nodeId?source:graphMaterialize(nodes.find(n=>n.id===start));writeTimelineSounds(destination,[...timelineSounds(destination).filter(t=>t.id!==base.id),{...clean,routeChoices:choices}]);return;}const override={...clean,start,routeChoices:choices},overrides=(base.routeOverrides||[]).filter(t=>JSON.stringify(t.routeChoices)!==JSON.stringify(choices));writeTimelineSounds(source,[...timelineSounds(source).filter(t=>t.id!==base.id),{...base,routeOverrides:[...overrides,override]}]);return;}
