 for(const n of allNodes){$('batchStart').add(new Option(n.label+' · '+(n.text||'').slice(0,18),n.id));$('batchEnd').add(new Option(n.label+' · '+(n.text||'').slice(0,18),n.id));}if(allNodes.some(n=>n.id===selected))$('batchStart').value=selected;
