function timelineTime(value){const text=String(value||'0').trim();if(!/^\d+(?::[0-5]?\d)?(?:\.\d+)?$/.test(text))throw Error('时间请填写秒数或 分:秒，例如 00:15');const parts=text.split(':').map(Number);return parts.length===2?parts[0]*60+parts[1]:parts[0];}
