function validateSoundTimeline(){const sources=Array.from(editor.querySelectorAll('[data-node-id]')),ids=new Set(sources.map(el=>el.dataset.nodeId));let routes=null;for(const source of sources)for(const base of timelineSounds(source))for(const track of timelineVersions(base)){if(track.end&&!ids.has(track.end))throw Error('声音结束页已删除，请在声音时间轴重新选择：'+(track.title||'未命名声音'));if(track.start&&!ids.has(track.start))throw Error('声音开始页已删除，请在声音时间轴重新选择：'+(track.title||'未命名声音'));if((track.routeChoices||[]).some(id=>!ids.has(id)))throw Error('声音所属的逻辑树线路已删除，请重新安排：'+(track.title||'未命名声音'));if(!mediaURL(track.url))throw Error('时间轴音频失效，请重新选择：'+(track.title||'未命名声音'));if(track.end||track.routeChoices?.length){if(!routes)routes=timelineRenderingRoutes||timelineRoutes().routes;if(routes.some(r=>r.nodes.some(n=>n.id===source.dataset.nodeId))&&!timelineRangePages(track.start||source.dataset.nodeId,track.end,track.routeChoices||[],routes).length)throw Error('音乐起止页不在对应的逻辑树线路，请重新设置：'+(track.title||'未命名声音'));}}}


