 enabled.onchange=()=>{checkpoint();source.dataset.storyTimed=enabled.checked?'yes':'no';if(enabled.checked){$('storyFull').checked=true;source.dataset.storyAuto='no';const options=source.querySelector('[data-field=options]');if(!Array.from(options.children).some(el=>el.dataset.nodeId===source.dataset.storyTimeout)){options.insertAdjacentHTML('beforeend',optionEditor('超时未操作',''));graphProjection(editor);source.dataset.storyTimeout=options.lastElementChild.dataset.nodeId;}}checkpoint();renderGraph(source);};
