 const secondsLabel=document.createElement('label'),seconds=document.createElement('input');secondsLabel.textContent='限时秒数';seconds.type='number';seconds.min='1';seconds.max='3600';seconds.step='1';seconds.value=timedSeconds(source);seconds.setAttribute('aria-label','限时秒数');seconds.onchange=()=>{checkpoint();source.dataset.storySeconds=String(Math.round(Math.max(1,Math.min(3600,Number(seconds.value)||10))));seconds.value=source.dataset.storySeconds;checkpoint();};secondsLabel.append(seconds);section.append(secondsLabel);
