 function paint(item,s){var text=item.fork.querySelector('.timed-countdown-text'),meter=item.fork.querySelector('.timed-meter>span'),value=left(s);var seconds=Math.ceil(value/1000);if(text)text.textContent='剩余 '+seconds+' 秒';if(s.second!==seconds){s.second=seconds;notify();}if(meter){var progress=Math.max(0,Math.min(1,value/item.total));meter.style.transform='scaleX('+progress+')';var bar=meter.parentElement;bar.setAttribute('aria-valuenow',String(Math.round(progress*100)));bar.setAttribute('aria-valuetext','剩余 '+seconds+' 秒');}}
