 function check(){queued=false;var running=false;if(restoring)return;items.forEach(function(item){var s=state(item),open=item.choices.some(function(c){return c.open;});if(open){s.remaining=left(s);s.deadline=0;s.done=true;return;}if(!visible(item)){if(s.deadline){s.remaining=left(s);s.deadline=0;notify();}return;}if(s.done){s.done=false;s.remaining=item.total;}if(!s.deadline){s.deadline=Date.now()+s.remaining;notify();}running=true;if(left(s)<=0)expire(item,s);else paint(item,s);});if(running&&!interval)interval=setInterval(check,100);else if(!running&&interval){clearInterval(interval);interval=0;}}
