(function(){const panel=$('previewPanel'),button=$('previewFullscreen');function sync(){const active=document.fullscreenElement===panel||panel.classList.contains('preview-expanded');button.textContent=active?'退出全屏':'全屏观看';button.setAttribute('aria-pressed',String(active));}button.addEventListener('click',async()=>{if(document.fullscreenElement===panel){await document.exitFullscreen();}else if(panel.classList.contains('preview-expanded')){panel.classList.remove('preview-expanded');}else{try{if(!panel.requestFullscreen)throw Error('unsupported');await panel.requestFullscreen();}catch(error){panel.classList.add('preview-expanded');}}sync();});document.addEventListener('fullscreenchange',sync);document.addEventListener('keydown',e=>{if(e.key==='Escape'){panel.classList.remove('preview-expanded');sync();}});$('previewScope').addEventListener('change',renderPreview);})();

