let previewProfileSession=null;
function previewProfileKey(){return 'paper-studio-sim-v1-'+book.id+'-'+($('previewScope').value==='all'?'book':'chapter-'+book.active)+'-'+$('previewPlayer').value;}
function preparePreviewProfile(markup){const holder=document.createElement('div');holder.innerHTML=markup;const root=holder.querySelector('.book-reader');if(previewEntryMode==='story'){previewProfileSession=null;root.setAttribute('data-preview-entry','story');if($('previewStart').value)root.setAttribute('data-preview-chapter',book.active);return holder.innerHTML;}root.setAttribute('data-preview-entry','cover');let records={},blocked=false;const key=previewProfileKey();try{const raw=localStorage.getItem(key),value=raw===null?legacyPreviewProfile():JSON.parse(raw);if(value&&typeof value==='object'&&!Array.isArray(value))records=value;}catch(error){blocked=true;notice('模拟玩家档案无法读取；未覆盖原记录。可用“重置此玩家”清空后重试。');}const token=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);previewProfileSession={key,token,records,blocked,profile:$('previewPlayer').value};root.setAttribute('data-preview-token',token);root.setAttribute('data-preview-store',JSON.stringify(records));return holder.innerHTML;}
function flushPreviewProfile(){return new Promise(resolve=>{const session=previewProfileSession,frame=$('previewFrame');if(!session||!frame.contentWindow)return resolve();const timeout=setTimeout(done,800);function done(){clearTimeout(timeout);window.removeEventListener('message',receive);resolve();}function receive(event){if(event.source===frame.contentWindow&&event.data&&event.data.type==='paper-preview-flushed'&&event.data.token===session.token)done();}window.addEventListener('message',receive);frame.contentWindow.postMessage({type:'paper-preview-flush',token:session.token},'*');});}
window.addEventListener('message',event=>{const session=previewProfileSession,data=event.data;if(!session||event.source!==$('previewFrame').contentWindow||!data||data.type!=='paper-preview-write'||data.token!==session.token||typeof data.key!=='string'||!data.record||typeof data.record!=='object')return;if(!/^(paper-reader-|paper-endings-)/.test(data.key)||data.key.length>500)return;const serialized=JSON.stringify(data.record);if(serialized.length>2*1024*1024){notice('模拟存档过大，未保存；请减少测试回顾记录。');return;}if(session.blocked)return;session.records[data.key]=data.record;try{localStorage.setItem(session.key,JSON.stringify(session.records));}catch(error){notice('模拟玩家档案保存失败，请检查浏览器存储空间。');}});
$('previewPlayer').addEventListener('change',async()=>{const selector=$('previewPlayer');selector.disabled=true;try{await flushPreviewProfile();renderPreview();}finally{selector.disabled=false;}});
$('previewPlayerReset').addEventListener('click',async()=>{if(!confirm('清空模拟玩家 '+$('previewPlayer').value+' 在当前预览范围内的进度、存档和结局收藏？不会影响正文或真实玩家。'))return;await flushPreviewProfile();try{localStorage.removeItem(previewProfileKey());renderPreview();}catch(error){notice('无法清空模拟档案：'+error.message);}});

let previewEntryMode='story',previewStoryScope='chapter';
function syncPreviewEntry(){const cover=previewEntryMode==='cover';$('previewScope').disabled=cover;$('previewFlagPicker').hidden=cover;$('previewCover').setAttribute('aria-pressed',String(cover));document.querySelector('.preview-player-label').hidden=!cover;$('previewPlayerReset').hidden=!cover;}
function setPreviewEntry(mode){const next=mode==='cover'?'cover':'story';if(next==='cover'&&previewEntryMode!=='cover'){previewStoryScope=$('previewScope').value;$('previewScope').value='all';}else if(next==='story'&&previewEntryMode==='cover')$('previewScope').value=previewStoryScope;previewEntryMode=next;syncPreviewEntry();}
$('previewCover').addEventListener('click',async()=>{await flushPreviewProfile();setPreviewEntry('cover');if(!previewView)showView('preview');else renderPreview();});
syncPreviewEntry();

function legacyPreviewProfile(){const records={};for(const chapter of book.chapters){const raw=localStorage.getItem('paper-studio-sim-v1-'+book.id+'-chapter-'+chapter.id+'-'+$('previewPlayer').value);if(!raw)continue;let stored;try{stored=JSON.parse(raw);}catch(error){continue;}if(!stored||typeof stored!=='object')continue;for(const [key,record] of Object.entries(stored)){if(!record||typeof record!=='object')continue;if(key.startsWith('paper-endings-')&&records[key]){for(const field of ['keys','seen'])records[key][field]=[...new Set([...(Array.isArray(records[key][field])?records[key][field]:[]),...(Array.isArray(record[field])?record[field]:[])])];}else if(!records[key]||Number(record.savedAt||0)>Number(records[key].savedAt||0))records[key]=record;}}return records;}
